// mqtt-in already parsed the JSON payload (datatype "json" on the node
// above) — this node's job is structural validation only: drop anything
// that doesn't have the shape the rest of the flow assumes, so a bad
// message never reaches the moving-average state.
const p = msg.payload;

if (!p || typeof p !== 'object') {
    node.warn('dropped: payload is not an object');
    return null;
}
if (typeof p.device_id !== 'string') {
    node.warn('dropped: missing/invalid device_id');
    return null;
}
if (typeof p.temperature_c !== 'number' || Number.isNaN(p.temperature_c)) {
    node.warn('dropped: missing/invalid temperature_c');
    return null;
}
if (typeof p.reporting_interval_s !== 'number') {
    node.warn('dropped: missing/invalid reporting_interval_s');
    return null;
}
if (typeof p.timestamp !== 'string') {
    node.warn('dropped: missing/invalid timestamp');
    return null;
}

return msg;

// Keeps the latest 5 temperature readings in flow context (survives
// across messages, resets on a Node-RED restart/deploy — that's the
// point: this is edge state, not a database). average_temperature_c is
// then what "the last five samples look like", not just this one sample.
const p = msg.payload;

let history = flow.get('temp_history') || [];
history.push(p.temperature_c);
if (history.length > 5) {
    history = history.slice(-5);
}
flow.set('temp_history', history);

const sum = history.reduce((a, b) => a + b, 0);
const average_temperature_c = Math.round((sum / history.length) * 100) / 100;

msg.payload = {
    device_id: p.device_id,
    timestamp: p.timestamp,
    temperature_c: p.temperature_c,
    average_temperature_c: average_temperature_c,
    reporting_interval_s: p.reporting_interval_s,
    alarm: average_temperature_c > 26
};

return msg;
